// Changes: Read the checked return type from the function symbol.
IrType ast_get_function_return_type(Ctx* ctx, AstNode* function) {
  AstNode* ident = ast_node_child(ctx, function, AST_DEF_IDENT);
  const SymtableData* symbol = ast_node_get_symbol(ident);
  if (symbol == NULL)
    THROW(E_INTERNAL_ERROR, "Missing symbol for function '%s'",
          ast_node_get_name(ident));

  return symbol->ir_type;
}

